for(const item of EXTENSION_DRILLS["spelling-control"])if(/maiuscol/.test(item.stem))item.case_sensitive=true;
export function extensionItems(lessonId,variation=0) {
  const items=EXTENSION_DRILLS[lessonId];
  if(!items)return null;
  const offset=((variation%items.length)+items.length)%items.length;
  return [...items.slice(offset),...items.slice(0,offset)].map(item=>({...item,id:lessonId+"-local-"+items.indexOf(item),options:[...item.options],accept:[...item.accept]}));
}
